const cfg = $('Config').first().json;
const TZ = 'America/Los_Angeles';
const now = DateTime.now().setZone(TZ);
// EMAIL-FREEZE RULE: date D locks at 14:00 PT on D-1. Today is NEVER writable.
const minOffset = now.hour >= 14 ? 2 : 1;
let fromOffset = Number(cfg.fromOffset);
if (fromOffset === -1) fromOffset = minOffset;
if (fromOffset < 1) throw new Error('Never write today or the past (email-locked).');
if (fromOffset < minOffset && !cfg.lateOverride) throw new Error('Email-freeze guard: earliest writable day is +' + minOffset + ' right now (' + now.toFormat('HH:mm') + ' PT).');
const from = now.plus({ days: fromOffset });
let to;
const days = Number(cfg.days);
if (days === -1) {
  to = (now.weekday >= 5 ? now.plus({ weeks: 1 }) : now).endOf('week');
  if (to < from) to = from;
} else {
  if (isNaN(days) || days < 1) throw new Error('Bad days');
  to = now.plus({ days: fromOffset + days - 1 });
}
const fromDate = from.toFormat('yyyy-LL-dd');
const toDate = to.toFormat('yyyy-LL-dd');
const nDays = Math.round(DateTime.fromISO(toDate).diff(DateTime.fromISO(fromDate), 'days').days) + 1;
if (nDays > 16) throw new Error('Window too large: ' + nDays);
const afterIso = DateTime.fromISO(fromDate + 'T00:00:00', { zone: TZ }).minus({ seconds: 1 }).toUTC().toISO({ suppressMilliseconds: true }); // -1s: Jobber 'after' is exclusive at the exact boundary (anytime visits sit at 00:00)
const beforeIso = DateTime.fromISO(toDate + 'T00:00:00', { zone: TZ }).plus({ days: 1 }).minus({ seconds: 1 }).toUTC().toISO({ suppressMilliseconds: true }); // -1s: Jobber 'before' is inclusive at the exact boundary (next-day anytime visits leaked in)
return [{ json: { fromDate, toDate, afterIso, beforeIso, days: nDays, dryRun: cfg.dryRun, maxWrites: cfg.maxWrites, windowHours: cfg.windowHours } }];

// Runaway/failed-planning guard for the polling loop.
const j = $input.first().json;
if ($runIndex > 40) throw new Error('Planning poll timeout (>10 min).');
const st = (j.status || '').toString().toUpperCase();
if (st.startsWith('E')) throw new Error('OptimoRoute planning error: ' + JSON.stringify(j).slice(0, 300));
return [{ json: j }];

const cfg = $('Window').first().json;
const out = [];
let d = DateTime.fromISO(cfg.fromDate);
const end = DateTime.fromISO(cfg.toDate);
while (d <= end) { out.push({ json: { date: d.toFormat('yyyy-LL-dd') } }); d = d.plus({ days: 1 }); }
return out;

const stops = []; const errs = [];
for (const it of $input.all()) {
  const j = it.json;
  if (!j || j.success === false) { errs.push(JSON.stringify(j).slice(0, 200)); continue; }
  for (const r of j.routes || []) for (const s of r.stops || []) stops.push({ orderNo: String(s.orderNo), driver: r.driverName, scheduledAtDt: s.scheduledAtDt });
}
if (errs.length) throw new Error('get_routes errors: ' + errs.join(' | '));
return [{ json: { stops } }];

// Cursor-loop pagination step: accumulate pages in node static data, retry throttles.
const sd = $getWorkflowStaticData('node');
if ($runIndex === 0) { sd.acc = []; sd.cursor = null; sd.retries = 0; }
const r = $input.first().json;
if (r.errors) {
  if (JSON.stringify(r.errors).includes('THROTTLED')) {
    sd.retries = (sd.retries || 0) + 1;
    if (sd.retries > 10) throw new Error('Jobber throttled 10x — giving up.');
    return [{ json: { done: false, retry: true, cursor: sd.cursor } }];
  }
  throw new Error('Jobber error: ' + JSON.stringify(r.errors).slice(0, 400));
}
sd.retries = 0;
const v = r.data && r.data.visits;
if (!v) throw new Error('Unexpected Jobber response: ' + JSON.stringify(r).slice(0, 300));
sd.acc.push(...(v.nodes || []));
sd.cursor = v.pageInfo.endCursor;
if (v.pageInfo.hasNextPage) {
  if (sd.acc.length > 4000) throw new Error('Runaway pagination (>4000 visits)');
  return [{ json: { done: false, retry: false, cursor: sd.cursor, sofar: sd.acc.length } }];
}
const visits = sd.acc; sd.acc = []; sd.cursor = null;
return [{ json: { done: true, visits } }];

const cfg = $('Window').first().json;
const TZ = 'America/Los_Angeles';
const byId = {};
for (const n of ($input.first().json.visits || [])) byId[n.id] = n;
const visits = Object.values(byId);
const toPT = iso => DateTime.fromISO(iso, { zone: 'utc' }).setZone(TZ);
const byNum = {};
for (const v of visits) {
  let num = null;
  try { num = Buffer.from(v.id, 'base64').toString('utf8').split('/').pop(); } catch (e) {}
  if (!num || !/^\d+$/.test(num)) num = v.id.replace(/[^a-zA-Z0-9]/g, '').slice(-10);
  byNum[num] = v;
}
const routed = $('Collect routes').first().json.stops;
const writes = [], moves = [], committedMoves = [], techMismatch = [], orphans = [];
const matched = new Set();
for (const s of routed) {
  const m = s.orderNo.match(/^(\d+)-(\w+)$/);
  if (!m) { orphans.push(s.orderNo); continue; }
  const vis = byNum[m[2]];
  if (!vis) { orphans.push(s.orderNo); continue; }
  matched.add(vis.id);
  const planDt = DateTime.fromFormat(s.scheduledAtDt, 'yyyy-LL-dd HH:mm:ss', { zone: TZ });
  if (!planDt.isValid) { orphans.push(s.orderNo + ' bad-dt'); continue; }
  const planDate = planDt.toFormat('yyyy-LL-dd'), planTime = planDt.toFormat('HH:mm');
  const curStart = toPT(vis.startAt);
  const curDate = curStart.toFormat('yyyy-LL-dd'), curTime = curStart.toFormat('HH:mm');
  const endPT = vis.endAt ? toPT(vis.endAt) : null;
  const winH = endPT ? endPT.diff(curStart, 'hours').hours : 99;
  const committed = curTime !== '00:00' && winH <= 6; // window-width sentinel, same as WF-1
  const jn = vis.job && vis.job.jobNumber;
  const isSet = vis.job && vis.job.startAt ? toPT(vis.job.startAt).toFormat('yyyy-LL-dd') === curDate : false;
  const users = (vis.assignedUsers && vis.assignedUsers.nodes) || [];
  const techName = users[0] && users[0].name && users[0].name.full;
  if (techName && techName !== s.driver) techMismatch.push('job ' + jn + ': jobber=' + techName + ' vs route=' + s.driver);
  const dayMove = planDate !== curDate;
  const timeChange = dayMove || planTime !== curTime;
  if (dayMove) {
    const rec = { job: String(jn), from: curDate, to: planDate, tech: s.driver, isSet, committed };
    moves.push(rec);
    if (committed || isSet) committedMoves.push(rec);
  }
  if (timeChange) writes.push({ visitId: vis.id, job: String(jn), date: planDate, time: planDt.toFormat('HH:mm:ss'), driver: s.driver, dayMove, isSet });
}
const unrouted = visits.filter(v => !matched.has(v.id)).map(v => {
  const jn = v.job && v.job.jobNumber;
  const d = toPT(v.startAt).toFormat('yyyy-LL-dd');
  const isSet = v.job && v.job.startAt ? toPT(v.job.startAt).toFormat('yyyy-LL-dd') === d : false;
  return { job: String(jn), date: d, isSet };
});
const unroutedSets = unrouted.filter(u => u.isSet);
// DELTA GUARD: committed/set visits must essentially never change days (allowedDates pins them
// in OR; if any slip through, something is wrong upstream) -> abort before any write.
if (committedMoves.length > 5) throw new Error('DELTA GUARD: ' + committedMoves.length + ' committed/set visits would change days — ABORTED, no writes. First: ' + JSON.stringify(committedMoves.slice(0, 5)));
return [{ json: {
  counts: { routedStops: routed.length, jobberVisits: visits.length, writes: writes.length, dayMoves: moves.length, committedMoves: committedMoves.length, unrouted: unrouted.length, unroutedSets: unroutedSets.length, orphans: orphans.length, techMismatch: techMismatch.length },
  writes, moves, committedMoves, unrouted: unrouted.slice(0, 50), unroutedSets, techMismatch: techMismatch.slice(0, 20), orphans: orphans.slice(0, 20)
} }];

function moveLines(plan) {
  const L = [];
  if (plan.moves.length) L.push('DAY MOVES (' + plan.moves.length + '): ' + plan.moves.slice(0, 30).map(m => 'job ' + m.job + ' ' + m.from + '->' + m.to + (m.isSet ? ' [SET!]' : '') + (m.committed ? ' [WAS-COMMITTED!]' : '')).join(' ; '));
  if (plan.unroutedSets.length) L.push('SETS NOT ROUTED — DECIDE (' + plan.unroutedSets.length + '): ' + plan.unroutedSets.map(u => 'job ' + u.job + ' ' + u.date).join(', '));
  if (plan.techMismatch.length) L.push('TECH MISMATCH (' + plan.techMismatch.length + '): ' + plan.techMismatch.join(' | '));
  if (plan.counts.unrouted) L.push('Unrouted visits in window: ' + plan.counts.unrouted);
  if (plan.counts.orphans) L.push('Orphan OR orders: ' + plan.counts.orphans);
  return L;
}
const cfg = $('Window').first().json;
const plan = $('Build plan').first().json;
const c = plan.counts;
const L = [];
L.push('WF-2 ROUTE (dry) ' + cfg.fromDate + ' -> ' + cfg.toDate);
L.push('Routed stops: ' + c.routedStops + ' | Jobber visits: ' + c.jobberVisits + ' | would write: ' + c.writes);
L.push(...moveLines(plan));
return [{ json: { title: 'WF-2 route ' + cfg.fromDate + '->' + cfg.toDate, mode: 'ROUTE-DRY', days: Number(cfg.days), scheduled: c.writes, timeFixed: 0, errors: 0, text: L.join('\n') } }];

const cfg = $('Window').first().json;
const max = Number(cfg.maxWrites || 0);
const wh = Number(cfg.windowHours || 3);
const plan = $('Build plan').first().json;
const TZ = 'America/Los_Angeles';
function sched(visitId, date, time) {
  const s = DateTime.fromISO(date + 'T' + time, { zone: TZ });
  const e = s.plus({ hours: wh });
  return 'mutation { visitEditSchedule(id: "' + visitId + '", input: { startAt: { date: "' + s.toFormat('yyyy-LL-dd') + '", time: "' + s.toFormat('HH:mm:ss') + '", timezone: "' + TZ + '" }, endAt: { date: "' + e.toFormat('yyyy-LL-dd') + '", time: "' + e.toFormat('HH:mm:ss') + '", timezone: "' + TZ + '" } }) { userErrors { message } } }';
}
const items = plan.writes.map(w => ({ kind: 'schedule', visitId: w.visitId, job: w.job, dayMove: w.dayMove, isSet: w.isSet, mutation: sched(w.visitId, w.date, w.time) }));
const capped = items.slice(0, max);
if (!capped.length) return [{ json: { noop: true, wouldWrite: items.length } }];
return capped.map(i => ({ json: i }));

function moveLines(plan) {
  const L = [];
  if (plan.moves.length) L.push('DAY MOVES (' + plan.moves.length + '): ' + plan.moves.slice(0, 30).map(m => 'job ' + m.job + ' ' + m.from + '->' + m.to + (m.isSet ? ' [SET!]' : '') + (m.committed ? ' [WAS-COMMITTED!]' : '')).join(' ; '));
  if (plan.unroutedSets.length) L.push('SETS NOT ROUTED — DECIDE (' + plan.unroutedSets.length + '): ' + plan.unroutedSets.map(u => 'job ' + u.job + ' ' + u.date).join(', '));
  if (plan.techMismatch.length) L.push('TECH MISMATCH (' + plan.techMismatch.length + '): ' + plan.techMismatch.join(' | '));
  if (plan.counts.unrouted) L.push('Unrouted visits in window: ' + plan.counts.unrouted);
  if (plan.counts.orphans) L.push('Orphan OR orders: ' + plan.counts.orphans);
  return L;
}
const cfg = $('Window').first().json;
const plan = $('Build plan').first().json;
const emitted = $('Emit writes').all().map(i => i.json);
let results = [];
try { results = $('Jobber mutate').all().map(i => i.json); } catch (e) {}
if (emitted.length === 1 && emitted[0].noop) {
  return [{ json: { title: 'WF-2 route ' + cfg.fromDate + '->' + cfg.toDate, mode: 'ROUTE-LIVE', days: Number(cfg.days), scheduled: 0, timeFixed: 0, errors: 0, text: 'NOOP: maxWrites=0 or nothing to write. Would write ' + emitted[0].wouldWrite + '.' } }];
}
let ok = 0, failed = 0; const errs = [];
for (let i = 0; i < emitted.length; i++) {
  const j = results[i] || {}; const ue = [];
  if (j.errors) ue.push(...j.errors.map(e => e.message));
  const d = j.data || {};
  for (const k of Object.keys(d)) if (d[k] && d[k].userErrors) ue.push(...d[k].userErrors.map(e => e.message));
  if (ue.length) { failed++; errs.push('job ' + emitted[i].job + ': ' + ue.join('; ')); } else ok++;
}
const L = [];
L.push('WF-2 ROUTE LIVE ' + cfg.fromDate + ' -> ' + cfg.toDate);
L.push('Writes: ' + emitted.length + ' attempted | ok ' + ok + ' | failed ' + failed);
L.push(...moveLines(plan));
if (errs.length) L.push('Errors: ' + errs.slice(0, 15).join(' | '));
return [{ json: { title: 'WF-2 route ' + cfg.fromDate + '->' + cfg.toDate, mode: 'ROUTE-LIVE', days: Number(cfg.days), scheduled: ok, timeFixed: 0, errors: failed, text: L.join('\n') } }];
